  "inlineSchema": "// Deloitte RFP Command Center - Enterprise Database Schema\n// PostgreSQL with Prisma ORM\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// USER MANAGEMENT & AUTHENTICATION\n// ============================================\n\n// UserRole strings: PROPOSAL_MANAGER, SOLUTION_ARCHITECT, LEADERSHIP, BID_REVIEWER\n\nmodel User {\n  id        String   @id @default(uuid())\n  email     String   @unique\n  password  String // Hashed\n  firstName String\n  lastName  String\n  role      String   @default(\"SOLUTION_ARCHITECT\")\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  managedRFPs   RFP[]          @relation(\"ProposalManager\")\n  assignedRFPs  RFP[]          @relation(\"AssignedArchitect\")\n  tasks         Task[]\n  approvals     Approval[]\n  activityLogs  ActivityLog[]\n  notifications Notification[]\n\n  @@index([email])\n  @@index([role])\n}\n\n// ============================================\n// RFP LIFECYCLE MANAGEMENT\n// ============================================\n\n// RFPStatus strings: INTAKE, QUALIFICATION, PLANNING, IN_PROGRESS, REVIEW, APPROVED, SUBMITTED, LOST, WON\n\n// RiskLevel strings: GREEN, AMBER, RED\n\n// GoNoGoDecision strings: PENDING, GO, NO_GO\n\nmodel RFP {\n  id                   String   @id @default(uuid())\n  rfpNumber            String   @unique\n  clientName           String\n  industry             String\n  projectTitle         String\n  executiveSummary     String?\n  submissionDeadline   DateTime\n  estimatedDealValue   Float\n  status               String   @default(\"INTAKE\")\n  riskLevel            String   @default(\"GREEN\")\n  goNoGoDecision       String   @default(\"PENDING\")\n  completionPercentage Int      @default(0)\n\n  // Ownership\n  proposalManagerId String\n  proposalManager   User   @relation(\"ProposalManager\", fields: [proposalManagerId], references: [id])\n\n  solutionArchitectId String?\n  solutionArchitect   User?   @relation(\"AssignedArchitect\", fields: [solutionArchitectId], references: [id])\n\n  // Timestamps\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  submittedAt DateTime?\n  wonLostAt   DateTime?\n\n  // Relations\n  tasks         Task[]\n  milestones    Milestone[]\n  approvals     Approval[]\n  activityLogs  ActivityLog[]\n  notifications Notification[]\n\n  @@index([status])\n  @@index([riskLevel])\n  @@index([submissionDeadline])\n  @@index([proposalManagerId])\n  @@index([solutionArchitectId])\n}\n\n// ============================================\n// TASK & OWNERSHIP GOVERNANCE\n// ============================================\n\n// TaskStatus strings: NOT_STARTED, IN_PROGRESS, BLOCKED, COMPLETED\n\nmodel Task {\n  id          String   @id @default(uuid())\n  title       String\n  description String?\n  dueDate     DateTime\n  status      String   @default(\"NOT_STARTED\")\n  isOverdue   Boolean  @default(false)\n  isEscalated Boolean  @default(false) // >48hrs overdue\n\n  // Single owner enforcement\n  ownerId String\n  owner   User   @relation(fields: [ownerId], references: [id])\n\n  rfpId String\n  rfp   RFP    @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  completedAt DateTime?\n\n  @@index([status])\n  @@index([dueDate])\n  @@index([isOverdue])\n  @@index([ownerId])\n  @@index([rfpId])\n}\n\n// ============================================\n// MILESTONE ENGINE\n// ============================================\n\n// MilestoneType strings: KICKOFF, DRAFT_1, INTERNAL_REVIEW, FINAL_REVIEW, SUBMISSION\n\nmodel Milestone {\n  id            String    @id @default(uuid())\n  type          String\n  title         String\n  targetDate    DateTime\n  completedDate DateTime?\n  isCompleted   Boolean   @default(false)\n  isDelayed     Boolean   @default(false)\n\n  rfpId String\n  rfp   RFP    @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([rfpId])\n  @@index([targetDate])\n  @@index([isCompleted])\n}\n\n// ============================================\n// APPROVAL WORKFLOW\n// ============================================\n\n// ApprovalType strings: DRAFT_APPROVAL, FINAL_APPROVAL, GO_NO_GO\n\n// ApprovalStatus strings: PENDING, APPROVED, REJECTED\n\nmodel Approval {\n  id       String  @id @default(uuid())\n  type     String\n  status   String  @default(\"PENDING\")\n  comments String?\n\n  reviewerId String\n  reviewer   User   @relation(fields: [reviewerId], references: [id])\n\n  rfpId String\n  rfp   RFP    @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime  @default(now())\n  decidedAt DateTime?\n\n  @@index([rfpId])\n  @@index([reviewerId])\n  @@index([status])\n}\n\n// ============================================\n// AUDIT COMPLIANCE - ACTIVITY LOGGING\n// ============================================\n\n// ActivityAction strings: RFP_CREATED, RFP_UPDATED, TASK_CREATED, TASK_ASSIGNED, TASK_UPDATED, STATUS_CHANGED, APPROVAL_REQUESTED, APPROVAL_DECIDED, RISK_ESCALATED, MILESTONE_COMPLETED\n\nmodel ActivityLog {\n  id          String @id @default(uuid())\n  action      String\n  description String\n  entityType  String // \"RFP\", \"Task\", \"Approval\"\n  entityId    String\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  rfpId String?\n  rfp   RFP?    @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([rfpId])\n  @@index([userId])\n  @@index([createdAt])\n  @@index([entityType, entityId])\n}\n\n// ============================================\n// NOTIFICATION SYSTEM\n// ============================================\n\n// NotificationType strings: TASK_ASSIGNED, DEADLINE_APPROACHING, RISK_ESCALATED, APPROVAL_REQUESTED, STATUS_CHANGED\n\nmodel Notification {\n  id      String  @id @default(uuid())\n  type    String\n  title   String\n  message String\n  isRead  Boolean @default(false)\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id])\n\n  rfpId String?\n  rfp   RFP?    @relation(fields: [rfpId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@index([isRead])\n  @@index([createdAt])\n}\n",
  "inlineSchemaHash": "ee77968dcdb4846833ca9de8d86bcdedf69f182533cdb910618df70bcd449a60",
